/**
 * Unknown paths go to /404.html rather than S3, which would return raw XML;
 * there are no distribution-wide error pages so /api and /assets keep their
 * real 403/404.
 *
 * Blog slugs fail open (any slug is served) until the publisher writes the
 * __synced__ sentinel, and on any KVS error, so live posts never 404.
 */
import cf from 'cloudfront';

var PUBLISHED_BLOG_SLUGS_OVERRIDE = null;

var OPTION_B_PREFIXES_OVERRIDE = null;

/* PUBLISH_SURFACE_BEGIN */
// Generated by services/publisher/scripts/generate-publish-surface.ts — do not edit by hand.
// Publisher targets contribute optionBPaths; Vite static pages are listed in
// STATIC_OPTION_B_PREFIXES (services/publisher/src/publish-targets/surface.ts).
var OPTION_B_PREFIXES = [
  '/blog',
  '/contact',
  '/dont-feed-the-bears',
  '/resume',
];
/* PUBLISH_SURFACE_END */

/** S3 keys stay under the storage prefix. */
var PUBLIC_POSTS_PREFIX = '/posts';
var STORAGE_POSTS_PREFIX = '/blog';

var LEGACY_RESUME_PDF = '/Christopher M Gagne Resume 2026.pdf';

async function handler(event) {
  var request = event.request;
  var host = request.headers.host.value.toLowerCase();

  if (host.indexOf('www.') === 0) {
    var apex = host.substring(4);
    return {
      statusCode: 301,
      statusDescription: 'Moved Permanently',
      headers: {
        location: {
          value:
            'https://' +
            apex +
            request.uri +
            serializeQueryString(request.querystring),
        },
      },
    };
  }

  var uri = request.uri;
  if (isLegacyResumePdfUri(uri)) {
    return {
      statusCode: 301,
      statusDescription: 'Moved Permanently',
      headers: {
        location: {
          value: '/resume.pdf' + serializeQueryString(request.querystring),
        },
      },
    };
  }

  var legacyPostsUri = swapPathPrefix(
    uri,
    STORAGE_POSTS_PREFIX,
    PUBLIC_POSTS_PREFIX,
  );
  if (legacyPostsUri !== null) {
    return {
      statusCode: 301,
      statusDescription: 'Moved Permanently',
      headers: {
        location: {
          value: legacyPostsUri + serializeQueryString(request.querystring),
        },
      },
    };
  }

  var storagePostsUri = swapPathPrefix(
    uri,
    PUBLIC_POSTS_PREFIX,
    STORAGE_POSTS_PREFIX,
  );
  if (storagePostsUri !== null) {
    uri = storagePostsUri;
    request.uri = uri;
  }

  if (
    uri === '/api' ||
    uri.indexOf('/api/') === 0 ||
    uri === '/media' ||
    uri.indexOf('/media/') === 0 ||
    uri === '/.well-known' ||
    uri.indexOf('/.well-known/') === 0
  ) {
    return request;
  }

  // The publisher's template, not a public URL.
  if (uri === '/_shell.html') {
    return {
      statusCode: 404,
      statusDescription: 'Not Found',
      headers: {
        'content-type': { value: 'text/plain; charset=utf-8' },
      },
      body: 'Not Found',
    };
  }

  if (uri === '/' || uri === '/index.html') {
    request.uri = '/index.html';
    return request;
  }

  if (isSpaShellPath(uri)) {
    request.uri = '/spa.html';
    return request;
  }

  if (isOptionBIndexPath(uri)) {
    request.uri = rewriteOptionB(uri);
    return request;
  }

  var blogSlug = blogPostSlug(uri);
  if (blogSlug !== null) {
    // Before KVS: __synced__ and over-long keys must not fail open.
    if (!isValidBlogSlug(blogSlug)) {
      request.uri = '/404.html';
      return request;
    }
    if (await isPublishedBlogSlug(blogSlug)) {
      request.uri = rewriteOptionB(uri);
    } else {
      request.uri = '/404.html';
    }
    return request;
  }

  if (uri.endsWith('/')) {
    request.uri = '/404.html';
  } else {
    var lastSlash = uri.lastIndexOf('/');
    var lastSegment = lastSlash === -1 ? uri : uri.substring(lastSlash + 1);
    if (lastSegment.indexOf('.') === -1) {
      request.uri = '/404.html';
    }
  }

  return request;
}

function swapPathPrefix(uri, from, to) {
  if (uri === from || uri.indexOf(from + '/') === 0) {
    return to + uri.substring(from.length);
  }
  return null;
}

function isSpaShellPath(uri) {
  return (
    uri === '/admin' ||
    uri === '/admin/' ||
    uri.indexOf('/admin/') === 0 ||
    uri === '/auth' ||
    uri === '/auth/' ||
    uri.indexOf('/auth/') === 0
  );
}

function effectiveOptionBPrefixes() {
  return OPTION_B_PREFIXES_OVERRIDE !== null
    ? OPTION_B_PREFIXES_OVERRIDE
    : OPTION_B_PREFIXES;
}

function isOptionBIndexPath(uri) {
  var prefixes = effectiveOptionBPrefixes();
  for (var i = 0; i < prefixes.length; i++) {
    var prefix = prefixes[i];
    if (uri === prefix || uri === prefix + '/') {
      return true;
    }
    // The slug allowlist owns nested /blog paths.
    if (prefix !== '/blog' && uri.indexOf(prefix + '/') === 0) {
      return true;
    }
  }
  return false;
}

function setOptionBPrefixesForTests(prefixes) {
  OPTION_B_PREFIXES_OVERRIDE = prefixes;
}

function blogPostSlug(uri) {
  if (uri.indexOf('/blog/') !== 0) {
    return null;
  }
  var rest = uri.substring('/blog/'.length);
  if (!rest || rest === 'index.html') {
    return null;
  }
  var slash = rest.indexOf('/');
  var segment = slash === -1 ? rest : rest.substring(0, slash);
  if (!segment || segment.indexOf('.') !== -1) {
    return null;
  }
  if (slash !== -1) {
    var after = rest.substring(slash + 1);
    if (after && after !== 'index.html') {
      return null;
    }
  }
  return segment;
}

/** Max length must match MAX_SLUG_LENGTH in @gagnechris/shared. */
function isValidBlogSlug(slug) {
  if (!slug || slug.length > 120) {
    return false;
  }
  if (
    slug.length >= 4 &&
    slug.indexOf('__') === 0 &&
    slug.substring(slug.length - 2) === '__'
  ) {
    return false;
  }
  for (var i = 0; i < slug.length; i++) {
    var c = slug.charCodeAt(i);
    var ok = (c >= 48 && c <= 57) || (c >= 97 && c <= 122) || c === 45;
    if (!ok) {
      return false;
    }
  }
  return true;
}

async function isPublishedBlogSlug(slug) {
  if (PUBLISHED_BLOG_SLUGS_OVERRIDE !== null) {
    return Object.prototype.hasOwnProperty.call(
      PUBLISHED_BLOG_SLUGS_OVERRIDE,
      slug,
    );
  }
  try {
    var kvsHandle = cf.kvs();
    // exists(slug) first: one KVS read for published posts.
    var slugExists;
    try {
      slugExists = await kvsHandle.exists(slug);
    } catch (e) {
      return true;
    }
    if (slugExists) {
      return true;
    }
    try {
      if (await kvsHandle.exists('__synced__')) {
        return false;
      }
      return true;
    } catch (e) {
      return true;
    }
  } catch (e) {
    return true;
  }
}

function setPublishedBlogSlugsForTests(slugs) {
  PUBLISHED_BLOG_SLUGS_OVERRIDE = slugs;
}

function rewriteOptionB(uri) {
  if (uri.endsWith('/')) {
    return uri + 'index.html';
  }
  var lastSlash = uri.lastIndexOf('/');
  var lastSegment = lastSlash === -1 ? uri : uri.substring(lastSlash + 1);
  if (lastSegment.indexOf('.') === -1) {
    return uri + '/index.html';
  }
  return uri;
}

/** CloudFront may pass the path percent-encoded or already decoded. */
function isLegacyResumePdfUri(uri) {
  var candidate = uri;
  for (var i = 0; i < 2; i++) {
    if (candidate === LEGACY_RESUME_PDF) {
      return true;
    }
    try {
      var decoded = decodeURIComponent(candidate);
      if (decoded === candidate) {
        break;
      }
      candidate = decoded;
    } catch (e) {
      break;
    }
  }
  return candidate === LEGACY_RESUME_PDF;
}

function serializeQueryString(qs) {
  if (!qs) {
    return '';
  }
  var parts = [];
  for (var key in qs) {
    if (!Object.prototype.hasOwnProperty.call(qs, key)) {
      continue;
    }
    var item = qs[key];
    if (item.multiValue) {
      for (var i = 0; i < item.multiValue.length; i++) {
        parts.push(key + '=' + item.multiValue[i].value);
      }
    } else if (item.value !== undefined) {
      parts.push(key + '=' + item.value);
    } else {
      parts.push(key + '=');
    }
  }
  return parts.length ? '?' + parts.join('&') : '';
}
